            require(bal5 == bal2 - amountToCollect);
            require(address(c).balance == cBeforeCollect - amountToCollect);
            require(address(this).balance == thisBeforeCollect + amountToCollect);

            assert(bal5 == bal2 - amountToCollect &&
                   address(c).balance == cBeforeCollect - amountToCollect);
        }
    }

